CREATE TABLE collaboration_workspaces (id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',autonomy_mode TEXT NOT NULL DEFAULT 'hybrid' CHECK(autonomy_mode IN ('directed','hybrid','autonomous')),max_agent_concurrency INTEGER NOT NULL DEFAULT 4 CHECK(max_agent_concurrency>0),max_delegation_depth INTEGER NOT NULL DEFAULT 3 CHECK(max_delegation_depth>=0),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE agent_identities (id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL REFERENCES collaboration_workspaces(id) ON DELETE CASCADE,definition_id TEXT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'worker',status TEXT NOT NULL DEFAULT 'offline' CHECK(status IN ('offline','idle','busy','paused','disabled')),capabilities_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(capabilities_json)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,name),FOREIGN KEY(definition_id) REFERENCES agent_definitions(id) ON DELETE SET NULL);
CREATE INDEX idx_agent_identities_workspace_status ON agent_identities(workspace_id,status);
CREATE TABLE collaboration_channels (id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL REFERENCES collaboration_workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('team','project','direct')),conversation_id TEXT NOT NULL UNIQUE REFERENCES conversations(id) ON DELETE RESTRICT,created_by TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,archived_at INTEGER);
CREATE INDEX idx_collaboration_channels_workspace ON collaboration_channels(workspace_id,created_at DESC);
CREATE TABLE collaboration_channel_members (channel_id TEXT NOT NULL REFERENCES collaboration_channels(id) ON DELETE CASCADE,agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'member',joined_at INTEGER NOT NULL,PRIMARY KEY(channel_id,agent_id));
CREATE TABLE collaboration_threads (id TEXT PRIMARY KEY NOT NULL,channel_id TEXT NOT NULL REFERENCES collaboration_channels(id) ON DELETE CASCADE,title TEXT NOT NULL DEFAULT '',root_message_id TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,closed_at INTEGER);
CREATE INDEX idx_collaboration_threads_channel ON collaboration_threads(channel_id,created_at DESC);
CREATE TABLE collaboration_tasks (id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL REFERENCES collaboration_workspaces(id) ON DELETE CASCADE,parent_task_id TEXT REFERENCES collaboration_tasks(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',task_type TEXT NOT NULL DEFAULT 'custom' CHECK(task_type IN ('research','coding','analysis','review','document','custom')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','assigned','in_progress','blocked','completed','canceled')),priority INTEGER NOT NULL DEFAULT 3 CHECK(priority BETWEEN 1 AND 5),created_by TEXT NOT NULL DEFAULT '',idempotency_key TEXT,delegation_depth INTEGER NOT NULL DEFAULT 0 CHECK(delegation_depth>=0),due_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE INDEX idx_collaboration_tasks_workspace_status ON collaboration_tasks(workspace_id,status,priority,created_at);
CREATE INDEX idx_collaboration_tasks_parent ON collaboration_tasks(parent_task_id);
CREATE TABLE task_assignments (id TEXT PRIMARY KEY NOT NULL,task_id TEXT NOT NULL REFERENCES collaboration_tasks(id) ON DELETE CASCADE,agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE RESTRICT,status TEXT NOT NULL CHECK(status IN ('pending','claimed','completed','rejected','expired','canceled')),assigned_by TEXT NOT NULL DEFAULT '',lease_owner TEXT NOT NULL DEFAULT '',lease_expires_at INTEGER,claim_version INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(task_id,agent_id));
CREATE INDEX idx_task_assignments_agent_status ON task_assignments(agent_id,status,created_at);
CREATE INDEX idx_task_assignments_lease ON task_assignments(status,lease_expires_at);
CREATE TABLE collaboration_outbox (id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,event_type TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at INTEGER NOT NULL,published_at INTEGER,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '');
CREATE INDEX idx_collaboration_outbox_pending ON collaboration_outbox(published_at,created_at);
CREATE TABLE collaboration_inbox (id TEXT PRIMARY KEY NOT NULL,agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE CASCADE,event_id TEXT NOT NULL,event_type TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','handled','ignored','failed')),received_at INTEGER NOT NULL,handled_at INTEGER,UNIQUE(agent_id,event_id));
CREATE INDEX idx_collaboration_inbox_pending ON collaboration_inbox(agent_id,status,received_at);
